import{_ as o,a0 as p,w as r,s as d,I as t,x as n,a1 as l,A as s,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何在 Arch Linux 的终端里设定 WiFi 网络 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 的终端里设定 WiFi 网络 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 的终端里设定 WiFi 网络 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 的终端里设定 WiFi 网络 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161026   How To Setup A WiFi Network In Arch Linux Using Terminal\uFEFF","title":"如何在 Arch Linux 的终端里设定 WiFi 网络","tag":"201611","desc":""},"relativePath":"201611/20161026   How To Setup A WiFi Network In Arch Linux Using Terminal\uFEFF.md","filePath":"[post].md"}'),u={name:"201611/20161026   How To Setup A WiFi Network In Arch Linux Using Terminal\uFEFF.md"};function h(c,i,g,k,w,f){const e=p("Link");return r(),d("div",null,[i[27]||(i[27]=t("h1",{id:"如何在-arch-linux-的终端里设定-wifi-网络",tabindex:"-1"},[n("如何在 Arch Linux 的终端里设定 WiFi 网络 "),t("a",{class:"header-anchor",href:"#如何在-arch-linux-的终端里设定-wifi-网络","aria-label":"Permalink to “如何在 Arch Linux 的终端里设定 WiFi 网络”"},"​")],-1)),i[28]||(i[28]=t("p",null,[t("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/how-to-connect-to-wifi-in-arch-linux-cli_orig.jpg",alt:"How To Setup A WiFi In Arch Linux Using Terminal\uFEFF"})],-1)),t("p",null,[i[2]||(i[2]=n("如果你使用的是其他 ",-1)),l(e,{href:"http://linuxandubuntu.com/home/category/distros"},{default:s(()=>[...i[0]||(i[0]=[n("Linux 发行版",-1)])]),_:1}),i[3]||(i[3]=n(" 而不是 ",-1)),l(e,{href:"http://www.linuxandubuntu.com/home/arch-linux-take-your-linux-knowledge-to-next-level-review"},{default:s(()=>[...i[1]||(i[1]=[n("Arch",-1)])]),_:1}),i[4]||(i[4]=n(" CLI，那么可能会不习惯在终端里设置 WiFi。尽管整个过程有点简单，不过我还是要讲一下。在这篇文章里，我将带领新手们通过一步步的设置向导，把你们的 Arch Linux 接入到你的 WiFi 网络里。",-1))]),i[29]||(i[29]=a('<p>在 Linux 里有很多程序来设置无线连接，我们可以用 <strong>ip</strong> 和 <strong>iw</strong> 来配置因特网连接，但是对于新手来说有点复杂。所以我们会使用 <strong>netctl</strong> 命令，这是一个基于命令行的工具，用来通过配置文件来设置和管理网络连接。</p><p>注意：所有的设定都需要 root 权限，或者你也可以使用 sudo 命令来完成。</p><h3 id="搜索网络" tabindex="-1">搜索网络 <a class="header-anchor" href="#搜索网络" aria-label="Permalink to “搜索网络”">​</a></h3><p>运行下面的命令来查看你的网络接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iwconfig</span></span></code></pre></div><p>运行如下命令启用你的网络接口，如果没有启用的话：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link set  interface up</span></span></code></pre></div><p>运行下面的命令搜索可用的 WiFi 网络。可以向下翻页来查看。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iwlist interface scan | less</span></span></code></pre></div><p><strong>注意：</strong> 命令里的 interface 是之前用 <strong>iwconfig</strong> 获取到的实际网络接口。</p><p>扫描完，如果不使用该接口可以运行如下命令关闭：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link set interface down</span></span></code></pre></div><h3 id="使用-netctl-配置-wi-fi" tabindex="-1">使用 netctl 配置 Wi-Fi： <a class="header-anchor" href="#使用-netctl-配置-wi-fi" aria-label="Permalink to “使用 netctl 配置 Wi-Fi：”">​</a></h3><p>在使用 <code>netctl</code> 设置连接之前，你必须先检查一下你的网卡在 Linux 下的兼容性。</p><p>运行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lspci -k</span></span></code></pre></div><p>这条命令是用来检查内核是否加载了你的无线网卡驱动。输出必须是像这样的：</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/arch-wifi-find-kernel-compatibility_orig.png" alt="arch linux wifi kernel compatibility "></p>',18)),t("p",null,[i[6]||(i[6]=n("如果内核没有加载驱动，你就必须使用有线连接来安装一下。这里是 Linux 无线网络的官方维基页面：",-1)),l(e,{href:"https://wireless.wiki.kernel.org/"},{default:s(()=>[...i[5]||(i[5]=[n("https://wireless.wiki.kernel.org/",-1)])]),_:1}),i[7]||(i[7]=n("。",-1))]),i[30]||(i[30]=a('<p>如果你的无线网卡和 Linux 兼容，你可以使用 <code>netctl configuration</code>。</p><p><code>netctl</code> 使用配置文件，这是一个包含连接信息的文件。创建这个文件有简单和困难两种方式。</p><h4 id="简单方式-–-wifi-menu" tabindex="-1">简单方式 – Wifi-menu <a class="header-anchor" href="#简单方式-–-wifi-menu" aria-label="Permalink to “简单方式 – Wifi-menu”">​</a></h4><p>如果你想用 <code>wifi-menu</code>，必须安装 <code>dialog</code>。</p><ol><li><p>运行命令: <code>wifi-menu</code></p></li><li><p>选择你的网络</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/wifi-menu-to-setup-wifi-in-arch_orig.png" alt="wifi-menu to setup wifi in arch"></p></li><li><p>输入正确的密码并等待</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/wifi-menu-type-wifi-password-in-arch.png?605" alt="wifi-menu setup wifi password in arch"></p></li></ol><p>如果没有连接失败的信息，你可以用下面的命令确认下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ping -c 3 www.google.com</span></span></code></pre></div><p>哇！如果你看到正在 ping，意味着网络设置成功。你现在已经在 Arch Linux 下连上 WiFi 了。如果有任何问题，可以倒回去重来。也许漏了什么。</p><h4 id="困难方式" tabindex="-1">困难方式 <a class="header-anchor" href="#困难方式" aria-label="Permalink to “困难方式”">​</a></h4><p>比起上面的 <code>wifi-menu</code> 命令，这种方式会难一点点，所以我叫做困难方式。在上面的命令里，网络配置会自动生成。而在困难方式里，我们将手动修改配置文件。不过不要担心，也没那么难。那我们开始吧！</p>',10)),t("ol",null,[t("li",null,[i[9]||(i[9]=t("p",null,[n("首先第一件事，你必须要知道网络接口的名字，通常会是 "),t("code",null,"wlan0"),n(" 或 "),t("code",null,"wlp2s0"),n("，但是也有很多例外。要确认你自己的网络接口，输入 "),t("code",null,"iwconfig"),n(" 命令并记下来。")],-1)),t("p",null,[l(e,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/scan-wifi-networks-in-arch-linux-cli_orig.png"},{default:s(()=>[...i[8]||(i[8]=[t("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/scan-wifi-networks-in-arch-linux-cli_orig.png",alt:"scan wifi networks in arch linux cli"},null,-1)])]),_:1})])]),i[10]||(i[10]=t("li",null,[t("p",null,"运行命令:")],-1))]),i[31]||(i[31]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /etc/netctl/examples</span></span></code></pre></div><p>在这个目录里，有很多不同的配置文件例子。</p><ol start="3"><li>拷贝将用到的配置文件例子到 <code>/etc/netctl/your_profile</code></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>	cp /etc/netctl/examples/wireless-wpa /etc/netctl/your_profile</span></span></code></pre></div><ol start="4"><li><p>你可以用这个命令来查看配置文件内容: <code>cat /etc/netctl/your_profile</code></p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/view-network-profile-in-arch-linux_orig.png" alt="view network profile in arch linux"></p></li><li><p>用 <code>vi</code> 或者 <code>nano</code> 编辑你的配置文件的下面几个部分：</p></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>	nano /etc/netctl/your_profile</span></span></code></pre></div><pre><code>	- `Interface`：比如说 `wlan0`\n	- `ESSID`：你的无线网络名字\n	- `key`：你的无线网络密码\n</code></pre><p><strong>注意:</strong></p><p>如果你不知道怎么用 <code>nano</code>，打开文件后，编辑要修改的地方，完了按 <code>ctrl+o</code>，然后回车，然后按 <code>ctrl+x</code>。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/edit-network-profile-in-arch_orig.png" alt="edit network profile in arch"></p><h3 id="运行-netctl" tabindex="-1">运行 netctl <a class="header-anchor" href="#运行-netctl" aria-label="Permalink to “运行 netctl”">​</a></h3><ol><li>运行命令：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>	cd /etc/netctl</span></span>\n<span class="line"><span>	ls</span></span></code></pre></div><pre><code>你一定会看到 `wifi-menu` 生成的配置文件，比如 `wlan0-SSID`；或者你选择了困难方式，你一定会看到你自己创建的配置文件。\n</code></pre><ol start="2"><li><p>运行命令启动连接配置：<code>netctl start your_profile</code>。</p></li><li><p>用下面的命令测试连接：</p></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>	ping -c 3 www.google.com</span></span></code></pre></div><pre><code>输出看上去像这样：\n![check internet connection in arch linux](http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/check-internet-connection-in-arch-linux_orig.png)      \n</code></pre><ol start="4"><li>最后，你必须运行下面的命令：<code>netctl enable your_profile</code>。</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>	netctl enable your_profile</span></span></code></pre></div><pre><code>这样将创建并激活一个 systemd 服务，然后开机时自动启动。然后欢呼吧！你在你的 Arch Linux 里配置好 wifi 网络啦。\n</code></pre><h3 id="其他工具" tabindex="-1">其他工具 <a class="header-anchor" href="#其他工具" aria-label="Permalink to “其他工具”">​</a></h3><p>你还可以使用其他程序来设置无线连接：</p><p>iw：</p><ol><li><code>iw dev wlan0 link</code> – 状态</li><li><code>iw dev wlan0 scan</code> – 搜索网络</li><li><code>iw dev wlan0 connect your_essid</code> – 连接到开放网络</li><li><code>iw dev wlan0 connect your_essid key your_key</code> - 使用 16 进制密钥连接到 WEP 加密的网络</li></ol><p>wpa_supplicant</p>',25)),t("ul",null,[t("li",null,[l(e,{href:"https://wiki.archlinux.org/index.php/WPA_supplicant"},{default:s(()=>[...i[11]||(i[11]=[n("https://wiki.archlinux.org/index.php/WPA_supplicant",-1)])]),_:1})])]),i[32]||(i[32]=t("p",null,"Wicd",-1)),t("ul",null,[t("li",null,[l(e,{href:"https://wiki.archlinux.org/index.php/wicd"},{default:s(()=>[...i[12]||(i[12]=[n("https://wiki.archlinux.org/index.php/wicd",-1)])]),_:1})])]),i[33]||(i[33]=t("p",null,"NetworkManager",-1)),t("ul",null,[t("li",null,[l(e,{href:"https://wiki.archlinux.org/index.php/NetworkManager"},{default:s(()=>[...i[13]||(i[13]=[n("https://wiki.archlinux.org/index.php/NetworkManager",-1)])]),_:1})])]),i[34]||(i[34]=t("h3",{id:"总结",tabindex:"-1"},[n("总结 "),t("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),i[35]||(i[35]=t("p",null,[n("会了吧！我提供了在 "),t("strong",null,"Arch Linux"),n(" 里接入 WiFI 网络的三种方式。这里有一件事我再强调一下，当你执行第一条命令的时候，请记住你的网络接口名字。在接下来搜索网络的命令里，请使用你的网络接口名字比如 "),t("code",null,"wlan0"),n(" 或 "),t("code",null,"wlp2s0"),n("（上一个命令里得到的），而不是用 interface 这个词。如果你碰到任何问题，可以在下面的评论区里直接留言给我。然后别忘了在你的朋友圈里和大家分享这篇文章哦。谢谢！")],-1)),i[36]||(i[36]=t("hr",null,null,-1)),t("p",null,[i[15]||(i[15]=n("via: ",-1)),l(e,{href:"http://www.linuxandubuntu.com/home/how-to-setup-a-wifi-in-arch-linux-using-terminal"},{default:s(()=>[...i[14]||(i[14]=[n("http://www.linuxandubuntu.com/home/how-to-setup-a-wifi-in-arch-linux-using-terminal",-1)])]),_:1})]),t("p",null,[i[19]||(i[19]=n("作者：",-1)),l(e,{href:"http://www.linuxandubuntu.com/contact-us.html"},{default:s(()=>[...i[16]||(i[16]=[n("Mohd Sohail",-1)])]),_:1}),i[20]||(i[20]=n(" 译者：",-1)),l(e,{href:"https://github.com/zpl1025"},{default:s(()=>[...i[17]||(i[17]=[n("zpl1025",-1)])]),_:1}),i[21]||(i[21]=n(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:s(()=>[...i[18]||(i[18]=[n("wxy",-1)])]),_:1})]),t("p",null,[i[24]||(i[24]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...i[22]||(i[22]=[n("LCTT",-1)])]),_:1}),i[25]||(i[25]=n(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:s(()=>[...i[23]||(i[23]=[n("Linux中国",-1)])]),_:1}),i[26]||(i[26]=n(" 荣誉推出",-1))])])}const y=o(u,[["render",h]]);export{m as __pageData,y as default};
